149	/** Fill a form field, or CLEAR it when the test gives no value. A refused submission leaves what
150	 *  was typed in the form (nothing in the contract says otherwise), so a value left over from the
151	 *  attempt before must never leak into this one: the test states every field it submits. A field
152	 *  the screen does not have is skipped. */
153	async function setField(scope: Locator | Page, testid: string, value: string | undefined): Promise<void> {
154	  const loc = scope.getByTestId(testid);
155	  if (value !== undefined) {
156	    await loc.fill(value);
157	  } else if ((await loc.count()) > 0) {
158	    await loc.fill('');
159	  }
160	}
