212	export async function loadSheet(page: Page, sheet: string): Promise<void> {
213	  await page.getByTestId('sheet-id-input').fill(sheet);
214	  await page.getByTestId('sheet-load').click();
215	  await expect(page.getByTestId('sheet-current-id')).toHaveText(sheet, { timeout: LOAD_WAIT });
