218	/** Re-load the active sheet so the screen shows what the store holds now. Loading the same id
219	 *  again is not observable (the current id already reads that), so the screen first loads a
220	 *  throwaway id, which has no one on it, and waits for the person rows to go; then it loads the
221	 *  sheet again and waits for rows to show. Rows that were on screen before may rightly not come
222	 *  back (someone retired since, say), so the wait is for any row, and for every row that is back
223	 *  to carry at least the claims it had; if none shows within the wait the screen is taken as it
224	 *  is and the test's own checks decide. The show-retired box and the as-of date, which belong to
225	 *  the screen, are put back if the loads reset them. */
226	export async function refresh(page: Page): Promise<void> {
227	  const sheet = (await page.getByTestId('sheet-current-id').textContent() ?? '').trim();
228	  const before = new Map<string, number>();
229	  for (const id of await ids(rows(page), 'person-row-')) before.set(id, await claimRows(row(page, id)).count());
230	  const retired = page.getByTestId('show-retired');
231	  const showRetiredWas = (await retired.count()) > 0 ? await retired.isChecked() : null;
232	  const asofWas = await shown(page.getByTestId('sheet-asof'));
233	  const previewWas = await shown(page.getByTestId('sheet-preview'));
234	  await loadSheet(page, sheet + '-reload');
235	  await expect.poll(() => rows(page).count(), { message: 'the throwaway sheet, which has no one on it, is on screen', timeout: LOAD_WAIT }).toBe(0);
236	  await loadSheet(page, sheet);
237	  if (showRetiredWas !== null && (await retired.isChecked()) !== showRetiredWas) await retired.setChecked(showRetiredWas);
238	  if (asofWas !== '' && (await shown(page.getByTestId('sheet-asof'))) !== asofWas) await setAsOf(page, asofWas);
239	  if (previewWas !== '' && (await shown(page.getByTestId('sheet-preview'))) !== previewWas) await setPreview(page, previewWas);
240	  if (before.size === 0) return;
241	  const back = async () => {
242	    if ((await rows(page).count()) === 0) return false;
243	    for (const [id, n] of before) {
244	      const r = row(page, id);
245	      if ((await r.count()) > 0 && (await claimRows(r).count()) < n) return false;
246	    }
247	    return true;
248	  };
249	  const deadline = Date.now() + LOAD_WAIT;
250	  while (Date.now() < deadline && !(await back())) await page.waitForTimeout(50);
251	}
