482	/** Paste lines of claims into the paste box: how many were added, or null when refused. */
483	export async function pasteClaims(page: Page, text: string): Promise<number | null> {
484	  // A paste that only updates DRAFTs in place adds no row: the count it shows is the
485	  // result, judged against the value before the click as countAfter judges it.
486	  const cell = page.getByTestId('paste-added');
487	  const before = await claimRows(page).count();
488	  const was = (await cell.count()) > 0 ? await shown(cell) : '';
489	  await page.getByTestId('paste-claims').fill(text);
490	  await page.getByTestId('paste-submit').click();
491	  let cleared = false;
492	  const counted = async () => {
493	    if ((await cell.count()) === 0) return false;
494	    const now = await shown(cell);
495	    if (now === '') { cleared = true; return false; }
496	    return now !== was || was === '' || cleared;
497	  };
498	  const ok = await until(page, async () => (await counted()) || (await claimRows(page).count()) > before,
499	    page.getByTestId('paste-error'), 'paste claims');
500	  return ok ? Number(await shown(cell)) : null;
501	}
