516	 *  no error has shown for a while (the `already` rule of until()). */
517	async function saveClaimEditor(page: Page, c: Locator, r: Locator, f: ClaimFields, what: string): Promise<boolean> {
518	  await fillClaimForm(r, f);
519	  const error = c.getByTestId('claim-error').or(r.getByTestId('claim-form-error'));
520	  const was = await editedCells(c, f);
521	  const already = await editedShows(c, f, was);
