526	/** A refused save leaves the editor open (the contract says a refusal changes nothing): close it
527	 *  with the cancel button when the screen has one, so the shared form is back to adding. */
528	async function cancelOpenEditor(c: Locator): Promise<void> {
529	  const cancel = c.getByTestId('claim-cancel');
