533	/** The cells an edit will be judged by, as they are before the save. */
534	async function editedCells(c: Locator, f: ClaimFields): Promise<Record<string, string>> {
535	  const out: Record<string, string> = {};
536	  for (const k of Object.keys(f)) out[k] = await shown(c.getByTestId(`claim-${k}`));
537	  return out;
538	}
539	
540	/** Whether the row shows the edit: an amount, date, note or corrects cell equal to what was
541	 *  typed; a ref or tags cell, which the app normalises, is taken as saved once the form's error
542	 *  is not showing and the cell is no longer what it was (or the typed value, normalised, is a
543	 *  value it could not have had before). */
544	async function editedShows(c: Locator, f: ClaimFields, was: Record<string, string>): Promise<boolean> {
545	  for (const [k, v] of Object.entries(f)) {
546	    const cell = await shown(c.getByTestId(`claim-${k}`));
547	    if (k === 'ref' || k === 'tags') {
548	      const norm = k === 'ref' ? v.trim() : v.split(',').map((t) => t.trim().toLowerCase()).filter((t) => t)
549	        .filter((t, i, a) => a.indexOf(t) === i).sort().join(', ');
550	      if (cell !== norm) return false;
551	    } else if (cell !== v) return false;
552	  }
553	  return true;
554	}
555	
556	/** Open a claim's editor (the edit button) and leave it open: true when the form filled with
557	 *  the claim's values, false when the claim refused (not editable, or locked by another user). */
558	export async function claimEditOpen(page: Page, claimId: string): Promise<boolean> {
559	  const c = claimRow(page, claimId);
560	  const r = personRowOf(page, claimId);
561	  const amount = await shown(c.getByTestId('claim-amount'));
562	  await c.getByTestId('claim-edit').click();
563	  return until(page, async () => (await r.getByTestId('claim-form-amount').inputValue().catch(() => '')) === amount
564	    && !(await c.getByTestId('claim-error').isVisible().catch(() => false)),
565	    c.getByTestId('claim-error'), 'open claim editor');
566	}
567	
568	/** Save the claim editor opened with claimEditOpen: true when the row shows the change. */
569	export async function claimEditSave(page: Page, claimId: string, f: ClaimFields): Promise<boolean> {
570	  const c = claimRow(page, claimId);
571	  const r = personRowOf(page, claimId);
572	  return saveClaimEditor(page, c, r, f, 'save claim editor');
573	}
574	
575	/** Change a draft's amount in the row (its own entry and save button): true when the row shows it. */
576	export async function editInline(page: Page, claimId: string, amount: string): Promise<boolean> {
577	    page.getByTestId('rate-preview-error'), 'rate preview');
578	  return ok ? { count: Number(await shown(countCell)), diff: await shown(diffCell) } : null;
579	}
