581	export async function claimEditCancel(page: Page, claimId: string): Promise<void> {
582	  await cancelOpenEditor(claimRow(page, claimId));
583	}
584	
585	/** open | settle | void | approve | reject(reason) | void(reason): true when the status changed.
586	 *  A reject's reason is typed; a void's is chosen from the sheet's list. */
587	export async function claimAction(page: Page, claimId: string, action: string, reason?: string): Promise<boolean> {
588	  const c = claimRow(page, claimId);
589	  const was = await shown(c.getByTestId('claim-status'));
590	  if (reason !== undefined && action === 'void') {
591	    try {
592	      await c.getByTestId('claim-void-reason').selectOption({ label: reason }, { timeout: 2000 });
593	    } catch {
594	      return false;             // not offered: the screen refuses it by leaving it out
595	    }
596	  } else if (reason !== undefined && action === 'settle') {
597	    await c.getByTestId('claim-settle-date').fill(reason);
598	  } else if (reason !== undefined) await c.getByTestId('claim-reject-reason').fill(reason);
599	  await c.getByTestId(`claim-${action}`).click();
600	  return until(page, async () => await shown(c.getByTestId('claim-status')) !== was,
601	    c.getByTestId('claim-error'), `claim ${action}`);
602	}
603	
604	/** Re-settle a settled claim: true once its status log gained a line. */
605	export async function resettle(page: Page, claimId: string): Promise<boolean> {
606	  const c = claimRow(page, claimId);
607	  const lines = c.getByTestId('claim-log-line');
608	  });
609	  test("claims scenario 3", { tag: '@functionality' }, async ({ browser }) => {
